print("Demo 4 cell-by-cell comparison (only non-bg positions):")
for r in range(9):
    for c in range(10):
        inp_val = d4_in[r][c]
        # Map to corresponding position after removing cols 2,7
        if c == 2 or c == 7:
            continue
        out_c_idx = c
        out_val = d4_out[r][out_c_idx]

        if inp_val != bg := d4_bg and out_val != d4_bg:
            print(f"D4({r},{c}): {inp_val} → {out_val}", end="")
            if inp_val == out_val:
                print(" ✓")
            else:
                print(" ✗ CHANGE!")

# Hmm wait, let me use proper variable assignment  
# Actually let me just do a systematic diff
from collections import defaultdict

changes = defaultdict(list)
matches = defaultdict(list)

for r in range(9):
    for c in range(10):
        if c == 2 or c == 7:
            continue
        inp = d4_in[r][c]
        out = d4_out[r][c]

        key = (r, c)
        if inp != out:
            changes[key].append((inp, out))
        else:
            matches[key].append(inp)

